fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
    // Determine how many participants we have to consider
    let limit = n.min(participations.len() as u8);

    // Count eligible participants
    let eligible_count = participations
        .iter()
        .take(limit as usize)
        .filter(|&&attendance| 5u8.saturating_sub(attendance) >= k)
        .count() as u8;

    // Return the number of teams (groups of 3 eligible participants)
    eligible_count / 3
}